<div class="breadcrumb"><a href="<?= $u() ?>">Home</a><span>/</span><span>Compare materials</span></div><div class="page-intro"><div><span class="eyebrow">COMPARE MATERIALS</span><h1>The details make the difference.</h1><p>Up to four materials, side by side. Compare actual selling units and finishes before choosing.</p></div><a class="button secondary" href="<?= $u('shop') ?>">Add a material ↗</a></div>
<?php if ($products): ?><div class="compare-wrap" tabindex="0" role="region" aria-label="Scrollable material comparison"><table class="compare-table"><caption class="sr-only">Selected material comparison</caption><thead><tr><th scope="col">Your shortlist<br><span class="note"><?= count($products) ?> of 4 materials</span></th><?php foreach ($products as $product): ?><th scope="col"><?php if ($product['images']): ?><img loading="lazy" src="<?= $u($product['images'][0]['path']) ?>" alt="<?= $e($product['images'][0]['alt_text']) ?>"><?php endif; ?><h2><?= $e($product['name']) ?></h2><form method="post" action="<?= $u('compare') ?>"><input type="hidden" name="csrf" value="<?= $e(RequestSecurity::csrfToken()) ?>"><input type="hidden" name="product_id" value="<?= $e($product['id']) ?>"><button class="text-button" name="action" value="remove" aria-label="Remove from comparison"><?= $icon('trash') ?></button></form></th><?php endforeach; ?></tr></thead><tbody>
