<tr><th scope="row">Availability</th><?php foreach ($products as $product): ?><td><?= $product['in_stock'] ? 'In stock — choose a variant' : 'Currently unavailable' ?></td><?php endforeach; ?></tr><tr><th scope="row">A closer look</th><?php foreach ($products as $product): ?><td><a class="button" href="<?= $u('product/'.$product['slug']) ?>">View material ↗</a></td><?php endforeach; ?></tr></tbody></table></div><?php else: ?><div class="empty-state"><h2>A little perspective helps.</h2><p>Use Compare on a product card to build your shortlist.</p><a class="button" href="<?= $u('shop') ?>">Explore materials ↗</a></div><?php endif; ?>
